changeSet.sql:
CREATE TABLE notification ( id UUID PRIMARY KEY, recipient_user_id UUID NOT NULL, channel VARCHAR(40) NOT NULL, status VARCHAR(40) NOT NULL, subject VARCHAR(255) NULL, body TEXT NULL, created_at TIMESTAMP NOT NULL );
CREATE TABLE notification_template ( id UUID PRIMARY KEY, code VARCHAR(120) NOT NULL UNIQUE, channel VARCHAR(40) NOT NULL, body TEXT NOT NULL );
CREATE TABLE notification_retry ( id UUID PRIMARY KEY, notification_id UUID NOT NULL REFERENCES notification(id), retry_count INT NOT NULL, next_retry_at TIMESTAMP NOT NULL );
